def _rollback_closure_phase3_h_staging(
    *,
    mode: str,
    physical_before: tuple[Any, ...],
    amend_before: tuple[Any, ...] | None,
    outcome_log_before: tuple[int, int, int, int, int, int, int, str],
    dvc_bin: str,
    dvc_status_before: Any,
    artifacts: list[DvcArtifact],
    unmanaged_before: list[Path],
    repo_root: Path,
    p_before: tuple[Any, ...] | None = None,
    u_before: tuple[Any, ...] | None = None,
) -> str | None:
    """Restore only the owned index paths and verify the unstaged boundary."""

    if mode == "runner_rewrite":
        scope = CLOSURE_PHASE3_H_RUNNER_REWRITE_STAGED_SCOPE
        selector = closure_phase3_h_runner_rewrite_pre_stage_scope
    elif mode == "authority_rewrite":
        scope = CLOSURE_PHASE3_H_AUTHORITY_REWRITE_STAGED_SCOPE
        selector = closure_phase3_h_authority_rewrite_pre_stage_scope
    elif mode == "import_repair":
        scope = CLOSURE_PHASE3_H_IMPORT_REPAIR_STAGED_SCOPE
        selector = closure_phase3_h_import_repair_pre_stage_scope
    elif mode == "amend":
        scope = CLOSURE_PHASE3_H_AMEND_STAGED_SCOPE
        selector = closure_phase3_h_amend_pre_stage_scope
    elif mode == "full":
        scope = CLOSURE_PHASE3_H_STAGED_SCOPE
        selector = closure_phase3_h_pre_stage_scope
    else:
        return f"unknown rollback mode: {mode}"

    errors: list[str] = []
    restore_command = [
        "git",
        "restore",
        "--staged",
        "--",
        *sorted(scope),
    ]
    try:
        restore_result = run_command(restore_command, check=False)
        if restore_result.returncode != 0:
            errors.append(
                "directed git restore --staged failed: "
                f"exit={restore_result.returncode}; stderr={restore_result.stderr.strip()}"
            )
    except BaseException as exc:
        errors.append(f"directed git restore --staged raised: {exc}")

    try:
        status = _git_output(
            repo_root,
            "status",
            "--short",
            "--untracked-files=all",
        )
        staged = _git_output(
            repo_root,
            "diff",
            "--cached",
            "--name-status",
            "--no-renames",
        )
        if staged.strip() or not selector(
            status,
            staged,
            repo_root=repo_root,
        ):
            errors.append(
                "directed rollback did not restore the exact fully-unstaged scope"
            )
    except BaseException as exc:
        errors.append(f"post-rollback Git scope validation failed: {exc}")

    try:
        if _snapshot_closure_phase3_h_files(
            repo_root=repo_root
        ) != physical_before:
            errors.append("post-rollback exact40 worktree snapshot drifted")
    except BaseException as exc:
        errors.append(f"post-rollback exact40 worktree recapture failed: {exc}")
    if mode == "runner_rewrite":
        try:
            if amend_before is None or (
                _snapshot_closure_phase3_h_runner_rewrite_files(
                    repo_root=repo_root
                )
                != amend_before
            ):
                errors.append("post-rollback runner exact4 worktree snapshot drifted")
        except BaseException as exc:
            errors.append(
                f"post-rollback runner exact4 worktree recapture failed: {exc}"
            )
        try:
            if p_before is None or (
                _snapshot_closure_phase3_p_runner_rewrite_files(
                    repo_root=repo_root
                )
                != p_before
            ):
                errors.append("post-rollback runner current P snapshot drifted")
        except BaseException as exc:
            errors.append(f"post-rollback runner current P validation failed: {exc}")
        try:
            if u_before is None or (
                _snapshot_closure_phase3_u_runner_rewrite_file(
                    repo_root=repo_root
                )
                != u_before
            ):
                errors.append("post-rollback runner current U snapshot drifted")
        except BaseException as exc:
            errors.append(f"post-rollback runner current U validation failed: {exc}")
        try:
            _require_closure_phase3_h_runner_rewrite_live_remote(
                repo_root=repo_root
            )
        except BaseException as exc:
            errors.append(f"post-rollback runner live remote validation failed: {exc}")
    elif mode == "authority_rewrite":
        try:
            if amend_before is None or (
                _snapshot_closure_phase3_h_authority_rewrite_files(
                    repo_root=repo_root
                )
                != amend_before
            ):
                errors.append("post-rollback exact4 worktree snapshot drifted")
        except BaseException as exc:
            errors.append(f"post-rollback exact4 worktree recapture failed: {exc}")
        try:
            if p_before is None or (
                _snapshot_closure_phase3_p_authority_rewrite_files(
                    repo_root=repo_root
                )
                != p_before
            ):
                errors.append("post-rollback exact10 P worktree snapshot drifted")
        except BaseException as exc:
            errors.append(f"post-rollback current P validation failed: {exc}")
        try:
            _require_closure_phase3_h_authority_rewrite_live_remote(
                repo_root=repo_root
            )
        except BaseException as exc:
            errors.append(f"post-rollback live remote validation failed: {exc}")
    elif mode == "import_repair":
        try:
            if amend_before is None or _snapshot_closure_phase3_h_import_repair_files(
                repo_root=repo_root
            ) != amend_before:
                errors.append("post-rollback exact5 worktree snapshot drifted")
        except BaseException as exc:
            errors.append(f"post-rollback exact5 worktree recapture failed: {exc}")
    elif mode == "amend":
        try:
            if amend_before is None or _snapshot_closure_phase3_h_amend_files(
                repo_root=repo_root
            ) != amend_before:
                errors.append("post-rollback exact13 worktree snapshot drifted")
        except BaseException as exc:
            errors.append(f"post-rollback exact13 worktree recapture failed: {exc}")

    try:
        if _closure_phase3_h_outcome_log_identity(
            repo_root=repo_root
        ) != outcome_log_before:
            errors.append("post-rollback outcome access log identity drifted")
    except BaseException as exc:
        errors.append(f"post-rollback outcome access log validation failed: {exc}")
    try:
        if mode == "runner_rewrite":
            _require_closure_phase3_h_runner_rewrite_future_paths_absent(
                repo_root=repo_root
            )
        elif mode == "authority_rewrite":
            _require_closure_phase3_h_authority_rewrite_future_paths_absent(
                repo_root=repo_root
            )
        else:
            _require_closure_phase3_h_unpublished_paths_absent(
                repo_root=repo_root
            )
    except BaseException as exc:
        errors.append(f"post-rollback P/U/exact52 absence validation failed: {exc}")
    try:
        if dvc_status_json(dvc_bin) != dvc_status_before:
            errors.append("post-rollback DVC status drifted")
    except BaseException as exc:
        errors.append(f"post-rollback DVC validation failed: {exc}")
    try:
        if unmanaged_ignored_heavy_paths(artifacts) != unmanaged_before:
            errors.append("post-rollback ignored-heavy inventory drifted")
    except BaseException as exc:
        errors.append(f"post-rollback ignored-heavy validation failed: {exc}")
    return "; ".join(errors) or None


def _abort_closure_phase3_h_post_add(
    primary: BaseException,
    *,
    mode: str,
    physical_before: tuple[Any, ...],
    amend_before: tuple[Any, ...] | None,
    outcome_log_before: tuple[int, int, int, int, int, int, int, str],
    dvc_bin: str,
    dvc_status_before: Any,
    artifacts: list[DvcArtifact],
    unmanaged_before: list[Path],
    repo_root: Path,
    p_before: tuple[Any, ...] | None = None,
    u_before: tuple[Any, ...] | None = None,
) -> int:
    rollback_error = _rollback_closure_phase3_h_staging(
        mode=mode,
        physical_before=physical_before,
        amend_before=amend_before,
        outcome_log_before=outcome_log_before,
        dvc_bin=dvc_bin,
        dvc_status_before=dvc_status_before,
        artifacts=artifacts,
        unmanaged_before=unmanaged_before,
        repo_root=repo_root,
        p_before=p_before,
        u_before=u_before,
    )
    label = {
        "runner_rewrite": "runner rewrite",
        "authority_rewrite": "authority rewrite",
        "import_repair": "import repair",
        "amend": "amendment",
        "full": "full H",
    }.get(mode, mode)
    if rollback_error is None:
        print(
            f"Closure Phase 3 {label} failed after staging: {primary}; "
            "the directed index rollback restored the exact unstaged scope.",
            file=sys.stderr,
        )
    else:
        print(
            f"Closure Phase 3 {label} failed after staging: {primary}; "
            f"ROLLBACK FAILED CLOSED: {rollback_error}",
            file=sys.stderr,
        )
    return 2


def _rollback_closure_phase3_recovery_staging(
    *,
    candidate_before: Mapping[str, RegistrationFileIdentity],
    log_before: RegistrationFileIdentity,
    u1_before: RegistrationFileIdentity,
    guard_before: tuple[int, int, int, int, int],
    dvc_bin: str,
    dvc_status_before: Any,
    artifacts: list[DvcArtifact],
    unmanaged_before: list[Path],
    repo_root: Path,
) -> str | None:
    """Restore only H2's index entries and recapture every durable boundary."""

    errors: list[str] = []
    try:
        result = run_command(
            [
                "git",
                "restore",
                "--staged",
                "--",
                *sorted(CLOSURE_PHASE3_H_RECOVERY_STAGED_SCOPE),
            ],
            check=False,
        )
        if result.returncode != 0:
            errors.append(
                "directed git restore --staged failed: "
                f"exit={result.returncode}; stderr={result.stderr.strip()}"
            )
    except BaseException as exc:
        errors.append(f"directed git restore --staged raised: {exc}")
    try:
        status = _git_output(
            repo_root, "status", "--short", "--untracked-files=all"
        )
        staged = _git_output(
            repo_root,
            "diff",
            "--cached",
            "--name-status",
            "--no-renames",
        )
        if staged.strip() or not closure_phase3_recovery_pre_stage_scope(
            status,
            staged,
            repo_root=repo_root,
        ):
            errors.append(
                "directed rollback did not restore exact14 fully unstaged"
            )
    except BaseException as exc:
        errors.append(f"post-rollback Git scope validation failed: {exc}")
    try:
        if (
            _snapshot_closure_phase3_recovery_candidate_files(
                repo_root=repo_root
            )
            != candidate_before
        ):
            errors.append("post-rollback exact14 worktree snapshot drifted")
    except BaseException as exc:
        errors.append(f"post-rollback exact14 recapture failed: {exc}")
    try:
        if _closure_phase3_recovery_log_identity(
            repo_root=repo_root
        ) != log_before:
            errors.append("post-rollback durable log prefix drifted")
    except BaseException as exc:
        errors.append(f"post-rollback durable log validation failed: {exc}")
    try:
        if _snapshot_closure_phase3_recovery_u1(
            repo_root=repo_root
        ) != u1_before:
            errors.append("post-rollback consumed U1 identity drifted")
    except BaseException as exc:
        errors.append(f"post-rollback U1 validation failed: {exc}")
    try:
        if _require_closure_phase3_recovery_guard(
            repo_root=repo_root, require_present=True
        ) != guard_before:
            errors.append("post-rollback consumed guard identity drifted")
    except BaseException as exc:
        errors.append(f"post-rollback consumed guard validation failed: {exc}")
    try:
        _require_closure_phase3_recovery_future_paths_absent(repo_root=repo_root)
        _require_closure_phase3_recovery_live_remote(repo_root=repo_root)
    except BaseException as exc:
        errors.append(f"post-rollback recovery boundary failed: {exc}")
    try:
        if dvc_status_json(dvc_bin) != dvc_status_before:
            errors.append("post-rollback DVC status drifted")
    except BaseException as exc:
        errors.append(f"post-rollback DVC validation failed: {exc}")
    try:
        if unmanaged_ignored_heavy_paths(artifacts) != unmanaged_before:
            errors.append("post-rollback ignored-heavy inventory drifted")
    except BaseException as exc:
        errors.append(f"post-rollback ignored-heavy validation failed: {exc}")
    return "; ".join(errors) or None


def _abort_closure_phase3_recovery_post_add(
    primary: BaseException,
    *,
    candidate_before: Mapping[str, RegistrationFileIdentity],
    log_before: RegistrationFileIdentity,
    u1_before: RegistrationFileIdentity,
    guard_before: tuple[int, int, int, int, int],
    dvc_bin: str,
    dvc_status_before: Any,
    artifacts: list[DvcArtifact],
    unmanaged_before: list[Path],
    repo_root: Path,
) -> int:
    rollback_error = _rollback_closure_phase3_recovery_staging(
        candidate_before=candidate_before,
        log_before=log_before,
        u1_before=u1_before,
        guard_before=guard_before,
        dvc_bin=dvc_bin,
        dvc_status_before=dvc_status_before,
        artifacts=artifacts,
        unmanaged_before=unmanaged_before,
        repo_root=repo_root,
    )
    if rollback_error is None:
        print(
            "Closure Phase 3 recovery H2 failed after staging: "
            f"{primary}; the directed index rollback restored exact14 and "
            "preserved the durable attempt-1 evidence.",
            file=sys.stderr,
        )
    else:
        print(
            "Closure Phase 3 recovery H2 failed after staging: "
            f"{primary}; ROLLBACK FAILED CLOSED: {rollback_error}",
            file=sys.stderr,
        )
    return 2


def _run_closure_phase3_recovery_precommit(
    args: Any,
    *,
    initial_status: str,
    repo_root: Path = Path("."),
) -> int:
    """Stage the append-only H2 recovery transition on consumed U1."""

    try:
        validate_closure_phase3_h_invocation(args)
        initial_staged = _git_output(
            repo_root,
            "diff",
            "--cached",
            "--name-status",
            "--no-renames",
        )
        if not closure_phase3_recovery_pre_stage_scope(
            initial_status,
            initial_staged,
            repo_root=repo_root,
        ):
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 recovery H2 exact14 scope disappeared"
            )
        candidate_before = (
            _snapshot_closure_phase3_recovery_candidate_files(
                repo_root=repo_root
            )
        )
        log_before = _closure_phase3_recovery_log_identity(repo_root=repo_root)
        u1_before = _snapshot_closure_phase3_recovery_u1(repo_root=repo_root)
        guard_before = _require_closure_phase3_recovery_guard(
            repo_root=repo_root, require_present=True
        )
        if guard_before is None:
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 recovery consumed guard disappeared"
            )
        _require_closure_phase3_recovery_future_paths_absent(repo_root=repo_root)
        _require_closure_phase3_recovery_live_remote(repo_root=repo_root)
        artifacts = load_configured_dvc_artifacts(args.manifest)
        unmanaged_before = unmanaged_ignored_heavy_paths(artifacts)
        dvc_bin, dvc_status_before = _initialize_precommit_dvc_observation(
            args.dvc_bin,
            formal_model_lock_active=False,
            require_locked_input_binary=False,
        )
        if dvc_bin != DEFAULT_DVC_BIN.as_posix() or dvc_status_before:
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 recovery requires exact empty repository "
                "DVC status"
            )
    except (
        ClosurePhase3HPrecommitAdapterError,
        ClosureLockedEvaluationInputBundleAdapterError,
    ) as exc:
        print(str(exc), file=sys.stderr)
        return 2

    report_path = default_report_path()
    try:
        publication_check_result, publication_compensated = (
            _run_closure_phase3_recovery_publication_check(repo_root=repo_root)
        )
    except ClosurePhase3HPrecommitAdapterError as exc:
        print(str(exc), file=sys.stderr)
        return 2
    publication_report_result = publication_check_result
    if publication_compensated:
        publication_report_result = CommandResult(
            publication_check_result.command,
            0,
            "OK: exact consumed-U1 two-path publication exception "
            "compensated; no other findings.\n",
            "",
        )

    try:
        status_before_add = _git_output(
            repo_root, "status", "--short", "--untracked-files=all"
        )
        index_before_add = _git_output(
            repo_root,
            "diff",
            "--cached",
            "--name-status",
            "--no-renames",
        )
        if not closure_phase3_recovery_pre_stage_scope(
            status_before_add,
            index_before_add,
            repo_root=repo_root,
        ):
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 recovery H2 changed during publication checks"
            )
        if (
            _snapshot_closure_phase3_recovery_candidate_files(
                repo_root=repo_root
            )
            != candidate_before
            or _closure_phase3_recovery_log_identity(repo_root=repo_root)
            != log_before
            or _snapshot_closure_phase3_recovery_u1(repo_root=repo_root)
            != u1_before
            or _require_closure_phase3_recovery_guard(
                repo_root=repo_root, require_present=True
            )
            != guard_before
        ):
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 recovery durable inputs changed before staging"
            )
        _require_closure_phase3_recovery_future_paths_absent(repo_root=repo_root)
        _require_closure_phase3_recovery_live_remote(repo_root=repo_root)
        if unmanaged_ignored_heavy_paths(artifacts) != unmanaged_before:
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 ignored-heavy inventory changed before "
                "recovery staging"
            )
    except ClosurePhase3HPrecommitAdapterError as exc:
        print(str(exc), file=sys.stderr)
        return 2

    git_add_result: CommandResult | None = None
    try:
        git_add_result = run_command(
            [
                "git",
                "add",
                "-A",
                "--",
                *sorted(CLOSURE_PHASE3_H_RECOVERY_STAGED_SCOPE),
            ],
            check=False,
        )
        if git_add_result.returncode != 0:
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 recovery directed git add failed: "
                f"exit={git_add_result.returncode}; "
                f"stderr={git_add_result.stderr.strip()}"
            )
        staged_snapshot = validate_closure_phase3_recovery_staged_transaction(
            repo_root=repo_root
        )
        if (
            staged_snapshot != candidate_before
            or _closure_phase3_recovery_log_identity(repo_root=repo_root)
            != log_before
            or _snapshot_closure_phase3_recovery_u1(repo_root=repo_root)
            != u1_before
            or _require_closure_phase3_recovery_guard(
                repo_root=repo_root, require_present=True
            )
            != guard_before
        ):
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 recovery durable inputs changed across staging"
            )
        _require_closure_phase3_recovery_future_paths_absent(repo_root=repo_root)
        _require_closure_phase3_recovery_live_remote(repo_root=repo_root)
        dvc_status_after = dvc_status_json(dvc_bin)
        if dvc_status_after != dvc_status_before:
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 DVC status changed during recovery staging"
            )
        staged_status = _git_output(
            repo_root,
            "diff",
            "--cached",
            "--name-status",
            "--no-renames",
        )
        findings = _compensate_closure_phase3_recovery_manifest_findings(
            reproducibility_checks(
            staged_status=staged_status,
            selected_dvc_paths=[],
            artifacts=artifacts,
            max_manifest_hash_bytes=args.max_manifest_hash_bytes,
            verify_manifest_inputs=args.verify_manifest_inputs,
            )
        )
        non_ok_findings = [
            finding for finding in findings if finding.level != "ok"
        ]
        if non_ok_findings:
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 recovery generic reproducibility checks "
                "contain warnings or failures: "
                + "; ".join(
                    finding.message for finding in non_ok_findings
                )
            )
        findings.extend(
            [
                ReproducibilityFinding(
                    "ok",
                    "phase3_recovery_scope",
                    "-",
                    "Exact H2 10M+4A staged as a direct append-only child "
                    "of consumed U1; no history rewrite is required.",
                ),
                ReproducibilityFinding(
                    "ok",
                    "phase3_recovery_attempt_1",
                    CLOSURE_E0_U_OUTCOME_ACCESS_LOG_PATH.as_posix(),
                    "The canonical 256-byte first-attempt log prefix, "
                    "failure receipt, consumed U1, and observed old guard "
                    "remained exact; the old guard was not removed or reused.",
                ),
                ReproducibilityFinding(
                    "ok",
                    "phase3_recovery_future",
                    "-",
                    "P2 exact7, U2 exact1, exact52 outputs, four future "
                    "pointers, and the recovery guard remain absent.",
                ),
                ReproducibilityFinding(
                    "ok",
                    "phase3_recovery_dvc",
                    "-",
                    "DVC stayed empty; no DVC add or push was run.",
                ),
                ReproducibilityFinding(
                    "ok",
                    "phase3_recovery_publication_guard",
                    CLOSURE_E0_U_ACTIVATION_PATH.as_posix(),
                    (
                        "Generic publication guard passed without compensation."
                        if not publication_compensated
                        else "Generic publication guard real rc=1 was "
                        "compensated only for the exact byte-bound consumed "
                        "U1 line containing its two sealed .venv paths."
                    ),
                ),
            ]
        )
        write_report(
            report_path,
            dry_run=False,
            selected_dvc_paths=[],
            deferred_dvc_paths=[],
            deferred_snapshot_before=None,
            deferred_snapshot_after=None,
            rejected_unmanaged_paths=unmanaged_before,
            git_status_before=initial_status,
            dvc_status_before=dvc_status_before,
            dvc_status_after=dvc_status_after,
            cloud_status_before=None,
            dvc_add_results=[],
            dvc_push_result=None,
            git_add_result=git_add_result,
            publication_check_result=publication_report_result,
            reproducibility_findings=findings,
            staged_status=staged_status,
            exclusive=True,
        )
        if (
            validate_closure_phase3_recovery_staged_transaction(
                repo_root=repo_root
            )
            != candidate_before
            or _closure_phase3_recovery_log_identity(repo_root=repo_root)
            != log_before
            or _snapshot_closure_phase3_recovery_u1(repo_root=repo_root)
            != u1_before
            or _require_closure_phase3_recovery_guard(
                repo_root=repo_root, require_present=True
            )
            != guard_before
            or dvc_status_json(dvc_bin) != dvc_status_before
            or unmanaged_ignored_heavy_paths(artifacts) != unmanaged_before
        ):
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 recovery changed while writing its report"
            )
        _require_closure_phase3_recovery_future_paths_absent(repo_root=repo_root)
        _require_closure_phase3_recovery_live_remote(repo_root=repo_root)
    except BaseException as exc:
        return _abort_closure_phase3_recovery_post_add(
            exc,
            candidate_before=candidate_before,
            log_before=log_before,
            u1_before=u1_before,
            guard_before=guard_before,
            dvc_bin=dvc_bin,
            dvc_status_before=dvc_status_before,
            artifacts=artifacts,
            unmanaged_before=unmanaged_before,
            repo_root=repo_root,
        )

    print()
    print(f"Report written: {report_path}")
    print(
        "Exact Closure Phase 3 recovery H2 10M+4A is staged; no DVC "
        "add or push ran. Publish H2 linearly, then generate P2 and U2."
    )
    return 0


def _rollback_closure_phase3_recovery_p2_staging(
    *,
    p2_before: Mapping[str, RegistrationFileIdentity],
    p1_before: tuple[RegistrationFileIdentity, ...],
    u1_before: RegistrationFileIdentity,
    log_before: RegistrationFileIdentity,
    guard_before: tuple[int, int, int, int, int] | None,
    h2_commit: str,
    dvc_bin: str,
    dvc_status_before: Any,
    artifacts: list[DvcArtifact],
    unmanaged_before: list[Path],
    repo_root: Path,
) -> str | None:
    errors: list[str] = []
    try:
        result = run_command(
            [
                "git",
                "restore",
                "--staged",
                "--",
                *sorted(CLOSURE_PHASE3_P_RECOVERY_STAGED_SCOPE),
            ],
            check=False,
        )
        if result.returncode != 0:
            errors.append(
                "directed P2 git restore --staged failed: "
                f"exit={result.returncode}; stderr={result.stderr.strip()}"
            )
    except BaseException as exc:
        errors.append(f"directed P2 git restore --staged raised: {exc}")
    try:
        status = _git_output(
            repo_root, "status", "--short", "--untracked-files=all"
        )
        staged = _git_output(
            repo_root,
            "diff",
            "--cached",
            "--name-status",
            "--no-renames",
        )
        if staged.strip() or not closure_phase3_recovery_p2_pre_stage_scope(
            status,
            staged,
            repo_root=repo_root,
        ):
            errors.append("P2 rollback did not restore exact7 fully unstaged")
    except BaseException as exc:
        errors.append(f"post-rollback P2 scope validation failed: {exc}")
    checks: tuple[tuple[str, Callable[[], Any], Any], ...] = (
        (
            "P2 exact7",
            lambda: _snapshot_closure_phase3_recovery_p2_files(
                repo_root=repo_root
            ),
            p2_before,
        ),
        (
            "P1 exact10",
            lambda: _snapshot_closure_phase3_p_files_at_commit(
                repo_root=repo_root,
                commit=CLOSURE_PHASE3_P_RECOVERY_COMMIT,
                context="recovery inherited",
            ),
            p1_before,
        ),
        (
            "U1",
            lambda: _snapshot_closure_phase3_recovery_u1(
                repo_root=repo_root
            ),
            u1_before,
        ),
        (
            "durable log",
            lambda: _closure_phase3_recovery_log_head_identity(
                repo_root=repo_root
            ),
            log_before,
        ),
        (
            "old guard",
            lambda: _require_closure_phase3_recovery_guard(
                repo_root=repo_root, require_present=False
            ),
            guard_before,
        ),
    )
    for label, recapture, expected in checks:
        try:
            if recapture() != expected:
                errors.append(f"post-rollback {label} identity drifted")
        except BaseException as exc:
            errors.append(f"post-rollback {label} validation failed: {exc}")
    try:
        _require_closure_phase3_recovery_refs_at(
            repo_root=repo_root, expected_commit=h2_commit, label="H2"
        )
        _require_closure_phase3_recovery_live_remote_at(
            repo_root=repo_root, expected_commit=h2_commit, label="H2"
        )
        _require_closure_phase3_recovery_post_h2_paths_absent(
            repo_root=repo_root
        )
    except BaseException as exc:
        errors.append(f"post-rollback P2 boundary failed: {exc}")
    try:
        if dvc_status_json(dvc_bin) != dvc_status_before:
            errors.append("post-rollback P2 DVC status drifted")
    except BaseException as exc:
        errors.append(f"post-rollback P2 DVC validation failed: {exc}")
    try:
        if unmanaged_ignored_heavy_paths(artifacts) != unmanaged_before:
            errors.append("post-rollback P2 ignored-heavy inventory drifted")
    except BaseException as exc:
        errors.append(f"post-rollback P2 ignored-heavy validation failed: {exc}")
    return "; ".join(errors) or None


def _run_closure_phase3_recovery_p2_precommit(
    args: Any,
    *,
    initial_status: str,
    repo_root: Path = Path("."),
) -> int:
    """Stage exact7A recovery evidence without touching inherited P1."""

    try:
        validate_closure_phase3_h_invocation(args)
        initial_staged = _git_output(
            repo_root,
            "diff",
            "--cached",
            "--name-status",
            "--no-renames",
        )
        if not closure_phase3_recovery_p2_pre_stage_scope(
            initial_status,
            initial_staged,
            repo_root=repo_root,
        ):
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 recovery P2 exact7 scope disappeared"
            )
        h2_commit = _git_output(repo_root, "rev-parse", "HEAD^{commit}").strip()
        p2_before = _snapshot_closure_phase3_recovery_p2_files(
            repo_root=repo_root
        )
        p1_before = _snapshot_closure_phase3_p_files_at_commit(
            repo_root=repo_root,
            commit=CLOSURE_PHASE3_P_RECOVERY_COMMIT,
            context="recovery inherited",
        )
        u1_before = _snapshot_closure_phase3_recovery_u1(repo_root=repo_root)
        log_before = _closure_phase3_recovery_log_head_identity(
            repo_root=repo_root
        )
        guard_before = _require_closure_phase3_recovery_guard(
            repo_root=repo_root, require_present=False
        )
        _require_closure_phase3_recovery_post_h2_paths_absent(repo_root=repo_root)
        _require_closure_phase3_recovery_live_remote_at(
            repo_root=repo_root, expected_commit=h2_commit, label="H2"
        )
        artifacts = load_configured_dvc_artifacts(args.manifest)
        unmanaged_before = unmanaged_ignored_heavy_paths(artifacts)
        dvc_bin, dvc_status_before = _initialize_precommit_dvc_observation(
            args.dvc_bin,
            formal_model_lock_active=False,
            require_locked_input_binary=False,
        )
        if dvc_bin != DEFAULT_DVC_BIN.as_posix() or dvc_status_before:
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 recovery P2 requires exact empty DVC status"
            )
    except (
        ClosurePhase3HPrecommitAdapterError,
        ClosureLockedEvaluationInputBundleAdapterError,
    ) as exc:
        print(str(exc), file=sys.stderr)
        return 2

    report_path = default_report_path()
    try:
        publication_result, publication_compensated = (
            _run_closure_phase3_recovery_publication_check(repo_root=repo_root)
        )
    except ClosurePhase3HPrecommitAdapterError as exc:
        print(str(exc), file=sys.stderr)
        return 2
    publication_report = publication_result
    if publication_compensated:
        publication_report = CommandResult(
            publication_result.command,
            0,
            "OK: exact consumed-U1 two-path publication exception "
            "compensated; no other findings.\n",
            "",
        )

    try:
        if not closure_phase3_recovery_p2_pre_stage_scope(
            _git_output(
                repo_root, "status", "--short", "--untracked-files=all"
            ),
            _git_output(
                repo_root,
                "diff",
                "--cached",
                "--name-status",
                "--no-renames",
            ),
            repo_root=repo_root,
        ):
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 recovery P2 changed before staging"
            )
        if (
            _snapshot_closure_phase3_recovery_p2_files(repo_root=repo_root)
            != p2_before
            or _snapshot_closure_phase3_p_files_at_commit(
                repo_root=repo_root,
                commit=CLOSURE_PHASE3_P_RECOVERY_COMMIT,
                context="recovery inherited",
            )
            != p1_before
            or _snapshot_closure_phase3_recovery_u1(repo_root=repo_root)
            != u1_before
            or _closure_phase3_recovery_log_head_identity(repo_root=repo_root)
            != log_before
            or _require_closure_phase3_recovery_guard(
                repo_root=repo_root, require_present=False
            )
            != guard_before
        ):
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 recovery P2 inputs changed before staging"
            )
    except ClosurePhase3HPrecommitAdapterError as exc:
        print(str(exc), file=sys.stderr)
        return 2

    try:
        git_add_result = run_command(
            [
                "git",
                "add",
                "-A",
                "--",
                *sorted(CLOSURE_PHASE3_P_RECOVERY_STAGED_SCOPE),
            ],
            check=False,
        )
        if git_add_result.returncode != 0:
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 recovery P2 directed git add failed"
            )
        if (
            validate_closure_phase3_recovery_p2_staged_transaction(
                repo_root=repo_root
            )
            != p2_before
            or _snapshot_closure_phase3_p_files_at_commit(
                repo_root=repo_root,
                commit=CLOSURE_PHASE3_P_RECOVERY_COMMIT,
                context="recovery inherited",
            )
            != p1_before
            or _snapshot_closure_phase3_recovery_u1(repo_root=repo_root)
            != u1_before
            or _closure_phase3_recovery_log_head_identity(repo_root=repo_root)
            != log_before
            or _require_closure_phase3_recovery_guard(
                repo_root=repo_root, require_present=False
            )
            != guard_before
        ):
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 recovery P2 inputs changed across staging"
            )
        dvc_status_after = dvc_status_json(dvc_bin)
        if dvc_status_after != dvc_status_before:
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 recovery P2 DVC status changed"
            )
        staged_status = _git_output(
            repo_root,
            "diff",
            "--cached",
            "--name-status",
            "--no-renames",
        )
        findings = reproducibility_checks(
            staged_status=staged_status,
            selected_dvc_paths=[],
            artifacts=artifacts,
            max_manifest_hash_bytes=args.max_manifest_hash_bytes,
            verify_manifest_inputs=args.verify_manifest_inputs,
        )
        non_ok = [finding for finding in findings if finding.level != "ok"]
        if non_ok:
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 recovery P2 reproducibility warning/failure: "
                + "; ".join(finding.message for finding in non_ok)
            )
        findings.extend(
            [
                ReproducibilityFinding(
                    "ok",
                    "phase3_recovery_p2_scope",
                    "-",
                    "Exact7A append-only E10 recovery evidence staged; "
                    "P1 exact10 remains inherited and unchanged.",
                ),
                ReproducibilityFinding(
                    "ok",
                    "phase3_recovery_p2_outcomes",
                    CLOSURE_E0_U_OUTCOME_ACCESS_LOG_PATH.as_posix(),
                    "Attempt-1 log prefix and guard policy remain exact; "
                    "U2, exact52, pointers, and recovery guard remain absent.",
                ),
                ReproducibilityFinding(
                    "ok",
                    "phase3_recovery_p2_dvc",
                    "-",
                    "DVC stayed empty; P2 ran no DVC add or push.",
                ),
            ]
        )
        write_report(
            report_path,
            dry_run=False,
            selected_dvc_paths=[],
            deferred_dvc_paths=[],
            deferred_snapshot_before=None,
            deferred_snapshot_after=None,
            rejected_unmanaged_paths=unmanaged_before,
            git_status_before=initial_status,
            dvc_status_before=dvc_status_before,
            dvc_status_after=dvc_status_after,
            cloud_status_before=None,
            dvc_add_results=[],
            dvc_push_result=None,
            git_add_result=git_add_result,
            publication_check_result=publication_report,
            reproducibility_findings=findings,
            staged_status=staged_status,
            exclusive=True,
        )
        if (
            validate_closure_phase3_recovery_p2_staged_transaction(
                repo_root=repo_root
            )
            != p2_before
            or dvc_status_json(dvc_bin) != dvc_status_before
            or unmanaged_ignored_heavy_paths(artifacts) != unmanaged_before
        ):
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 recovery P2 changed while writing report"
            )
        _require_closure_phase3_recovery_live_remote_at(
            repo_root=repo_root, expected_commit=h2_commit, label="H2"
        )
    except BaseException as exc:
        rollback_error = _rollback_closure_phase3_recovery_p2_staging(
            p2_before=p2_before,
            p1_before=p1_before,
            u1_before=u1_before,
            log_before=log_before,
            guard_before=guard_before,
            h2_commit=h2_commit,
            dvc_bin=dvc_bin,
            dvc_status_before=dvc_status_before,
            artifacts=artifacts,
            unmanaged_before=unmanaged_before,
            repo_root=repo_root,
        )
        if rollback_error is None:
            print(
                "Closure Phase 3 recovery P2 failed after staging: "
                f"{exc}; directed rollback restored exact7 unstaged.",
                file=sys.stderr,
            )
        else:
            print(
                "Closure Phase 3 recovery P2 failed after staging: "
                f"{exc}; ROLLBACK FAILED CLOSED: {rollback_error}",
                file=sys.stderr,
            )
        return 2

    print()
    print(f"Report written: {report_path}")
    print(
        "Exact Closure Phase 3 recovery P2 exact7A is staged; inherited P1 "
        "and DVC were unchanged. Publish P2, then generate U2."
    )
    return 0


def _rollback_closure_phase3_recovery_u2_staging(
    *,
    u2_before: RegistrationFileIdentity,
    p2_before: Mapping[str, RegistrationFileIdentity],
    u1_before: RegistrationFileIdentity,
    log_before: RegistrationFileIdentity,
    guard_before: tuple[int, int, int, int, int] | None,
    h2_commit: str,
    p2_commit: str,
    dvc_bin: str,
    dvc_status_before: Any,
    artifacts: list[DvcArtifact],
    unmanaged_before: list[Path],
    repo_root: Path,
) -> str | None:
    errors: list[str] = []
    try:
        result = run_command(
            [
                "git",
                "restore",
                "--staged",
                "--",
                CLOSURE_E0_U_RECOVERY_ACTIVATION_PATH.as_posix(),
            ],
            check=False,
        )
        if result.returncode != 0:
            errors.append(
                "directed U2 git restore --staged failed: "
                f"exit={result.returncode}; stderr={result.stderr.strip()}"
            )
    except BaseException as exc:
        errors.append(f"directed U2 git restore --staged raised: {exc}")
    try:
        status = _git_output(
            repo_root, "status", "--short", "--untracked-files=all"
        )
        staged = _git_output(
            repo_root, "diff", "--cached", "--name-status", "--no-renames"
        )
        if staged.strip() or not closure_phase3_recovery_u2_pre_stage_scope(
            status, staged, repo_root=repo_root
        ):
            errors.append("U2 rollback did not restore exact1 fully unstaged")
    except BaseException as exc:
        errors.append(f"post-rollback U2 scope validation failed: {exc}")
    checks: tuple[tuple[str, Callable[[], Any], Any], ...] = (
        (
            "U2",
            lambda: _snapshot_closure_phase3_recovery_u2_file(
                repo_root=repo_root,
                h2_commit=h2_commit,
                p2_commit=p2_commit,
            ),
            u2_before,
        ),
        (
            "P2 exact7",
            lambda: _snapshot_closure_phase3_recovery_p2_files(
                repo_root=repo_root
            ),
            p2_before,
        ),
        (
            "U1",
            lambda: _snapshot_closure_phase3_recovery_u1(
                repo_root=repo_root
            ),
            u1_before,
        ),
        (
            "durable log",
            lambda: _closure_phase3_recovery_log_head_identity(
                repo_root=repo_root
            ),
            log_before,
        ),
        (
            "old guard",
            lambda: _require_closure_phase3_recovery_guard(
                repo_root=repo_root, require_present=False
            ),
            guard_before,
        ),
    )
    for label, recapture, expected in checks:
        try:
            if recapture() != expected:
                errors.append(f"post-rollback {label} identity drifted")
        except BaseException as exc:
            errors.append(f"post-rollback {label} validation failed: {exc}")
    try:
        _require_closure_phase3_recovery_refs_at(
            repo_root=repo_root, expected_commit=p2_commit, label="P2"
        )
        _require_closure_phase3_recovery_live_remote_at(
            repo_root=repo_root, expected_commit=p2_commit, label="P2"
        )
        _require_closure_phase3_recovery_post_h2_paths_absent(
            repo_root=repo_root, allow_recovery_activation=True
        )
        _validate_closure_phase3_recovery_p2_bundle(
            repo_root=repo_root,
            h2_commit=h2_commit,
            require_git_publication=True,
            allowed_dirty_paths=(
                CLOSURE_E0_U_RECOVERY_ACTIVATION_PATH.as_posix(),
            ),
        )
    except BaseException as exc:
        errors.append(f"post-rollback U2 boundary failed: {exc}")
    try:
        if dvc_status_json(dvc_bin) != dvc_status_before:
            errors.append("post-rollback U2 DVC status drifted")
    except BaseException as exc:
        errors.append(f"post-rollback U2 DVC validation failed: {exc}")
    try:
        if unmanaged_ignored_heavy_paths(artifacts) != unmanaged_before:
            errors.append("post-rollback U2 ignored-heavy inventory drifted")
    except BaseException as exc:
        errors.append(f"post-rollback U2 ignored-heavy validation failed: {exc}")
    return "; ".join(errors) or None


def _run_closure_phase3_recovery_u2_precommit(
    args: Any,
    *,
    initial_status: str,
    repo_root: Path = Path("."),
) -> int:
    """Stage exact1A recovery authority without touching attempt-one evidence."""

    try:
        validate_closure_phase3_h_invocation(args)
        initial_staged = _git_output(
            repo_root, "diff", "--cached", "--name-status", "--no-renames"
        )
        if not closure_phase3_recovery_u2_pre_stage_scope(
            initial_status, initial_staged, repo_root=repo_root
        ):
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 recovery U2 exact1 scope disappeared"
            )
        p2_commit = _git_output(repo_root, "rev-parse", "HEAD^{commit}").strip()
        h2_commit = _require_closure_phase3_recovery_p2_history(
            repo_root=repo_root, p2_commit=p2_commit
        )
        u2_before = _snapshot_closure_phase3_recovery_u2_file(
            repo_root=repo_root, h2_commit=h2_commit, p2_commit=p2_commit
        )
        p2_before = _snapshot_closure_phase3_recovery_p2_files(
            repo_root=repo_root
        )
        u1_before = _snapshot_closure_phase3_recovery_u1(repo_root=repo_root)
        log_before = _closure_phase3_recovery_log_head_identity(
            repo_root=repo_root
        )
        guard_before = _require_closure_phase3_recovery_guard(
            repo_root=repo_root, require_present=False
        )
        _require_closure_phase3_recovery_post_h2_paths_absent(
            repo_root=repo_root, allow_recovery_activation=True
        )
        _require_closure_phase3_recovery_live_remote_at(
            repo_root=repo_root, expected_commit=p2_commit, label="P2"
        )
        artifacts = load_configured_dvc_artifacts(args.manifest)
        unmanaged_before = unmanaged_ignored_heavy_paths(artifacts)
        dvc_bin, dvc_status_before = _initialize_precommit_dvc_observation(
            args.dvc_bin,
            formal_model_lock_active=False,
            require_locked_input_binary=False,
        )
        if dvc_bin != DEFAULT_DVC_BIN.as_posix() or dvc_status_before:
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 recovery U2 requires exact empty DVC status"
            )
    except (
        ClosurePhase3HPrecommitAdapterError,
        ClosureLockedEvaluationInputBundleAdapterError,
    ) as exc:
        print(str(exc), file=sys.stderr)
        return 2

    report_path = default_report_path()
    try:
        publication_result = _run_closure_phase3_recovery_u2_publication_check(
            repo_root=repo_root,
            h2_commit=h2_commit,
            p2_commit=p2_commit,
        )
    except ClosurePhase3HPrecommitAdapterError as exc:
        print(str(exc), file=sys.stderr)
        return 2
    publication_report = CommandResult(
        publication_result.command,
        0,
        "OK: exact U1/U2 sealed-runtime path findings compensated; "
        "no other publication findings.\n",
        "",
    )

    try:
        if not closure_phase3_recovery_u2_pre_stage_scope(
            _git_output(
                repo_root, "status", "--short", "--untracked-files=all"
            ),
            _git_output(
                repo_root, "diff", "--cached", "--name-status", "--no-renames"
            ),
            repo_root=repo_root,
        ):
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 recovery U2 changed before staging"
            )
        if (
            _snapshot_closure_phase3_recovery_u2_file(
                repo_root=repo_root,
                h2_commit=h2_commit,
                p2_commit=p2_commit,
            )
            != u2_before
            or _snapshot_closure_phase3_recovery_p2_files(repo_root=repo_root)
            != p2_before
            or _snapshot_closure_phase3_recovery_u1(repo_root=repo_root)
            != u1_before
            or _closure_phase3_recovery_log_head_identity(repo_root=repo_root)
            != log_before
            or _require_closure_phase3_recovery_guard(
                repo_root=repo_root, require_present=False
            )
            != guard_before
        ):
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 recovery U2 inputs changed before staging"
            )
    except ClosurePhase3HPrecommitAdapterError as exc:
        print(str(exc), file=sys.stderr)
        return 2

    try:
        git_add_result = run_command(
            [
                "git",
                "add",
                "-A",
                "--",
                CLOSURE_E0_U_RECOVERY_ACTIVATION_PATH.as_posix(),
            ],
            check=False,
        )
        if git_add_result.returncode != 0:
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 recovery U2 directed git add failed"
            )
        if (
            validate_closure_phase3_recovery_u2_staged_transaction(
                repo_root=repo_root
            )
            != u2_before
            or _snapshot_closure_phase3_recovery_p2_files(repo_root=repo_root)
            != p2_before
            or _snapshot_closure_phase3_recovery_u1(repo_root=repo_root)
            != u1_before
            or _closure_phase3_recovery_log_head_identity(repo_root=repo_root)
            != log_before
            or _require_closure_phase3_recovery_guard(
                repo_root=repo_root, require_present=False
            )
            != guard_before
        ):
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 recovery U2 inputs changed across staging"
            )
        dvc_status_after = dvc_status_json(dvc_bin)
        if dvc_status_after != dvc_status_before:
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 recovery U2 DVC status changed"
            )
        staged_status = _git_output(
            repo_root, "diff", "--cached", "--name-status", "--no-renames"
        )
        findings = reproducibility_checks(
            staged_status=staged_status,
            selected_dvc_paths=[],
            artifacts=artifacts,
            max_manifest_hash_bytes=args.max_manifest_hash_bytes,
            verify_manifest_inputs=args.verify_manifest_inputs,
        )
        non_ok = [finding for finding in findings if finding.level != "ok"]
        if non_ok:
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 recovery U2 reproducibility warning/failure: "
                + "; ".join(finding.message for finding in non_ok)
            )
        findings.extend(
            [
                ReproducibilityFinding(
                    "ok",
                    "phase3_recovery_u2_scope",
                    CLOSURE_E0_U_RECOVERY_ACTIVATION_PATH.as_posix(),
                    "Exact1A recovery activation staged on published P2.",
                ),
                ReproducibilityFinding(
                    "ok",
                    "phase3_recovery_u2_attempt_1",
                    CLOSURE_E0_U_OUTCOME_ACCESS_LOG_PATH.as_posix(),
                    "Attempt-1 log prefix and optional historical guard "
                    "remain byte/identity exact.",
                ),
                ReproducibilityFinding(
                    "ok",
                    "phase3_recovery_u2_future",
                    CLOSURE_PHASE3_RECOVERY_NEW_GUARD_PATH.as_posix(),
                    "Exact52, future pointers, and recovery guard remain absent.",
                ),
                ReproducibilityFinding(
                    "ok",
                    "phase3_recovery_u2_publication_guard",
                    CLOSURE_E0_U_RECOVERY_ACTIVATION_PATH.as_posix(),
                    "The generic publication guard returned rc=1 solely for "
                    "the exact two sealed .venv paths in U1 and U2.",
                ),
            ]
        )
        write_report(
            report_path,
            dry_run=False,
            selected_dvc_paths=[],
            deferred_dvc_paths=[],
            deferred_snapshot_before=None,
            deferred_snapshot_after=None,
            rejected_unmanaged_paths=unmanaged_before,
            git_status_before=initial_status,
            dvc_status_before=dvc_status_before,
            dvc_status_after=dvc_status_after,
            cloud_status_before=None,
            dvc_add_results=[],
            dvc_push_result=None,
            git_add_result=git_add_result,
            publication_check_result=publication_report,
            reproducibility_findings=findings,
            staged_status=staged_status,
            exclusive=True,
        )
        if (
            validate_closure_phase3_recovery_u2_staged_transaction(
                repo_root=repo_root
            )
            != u2_before
            or dvc_status_json(dvc_bin) != dvc_status_before
            or unmanaged_ignored_heavy_paths(artifacts) != unmanaged_before
        ):
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 recovery U2 changed while writing report"
            )
        _require_closure_phase3_recovery_live_remote_at(
            repo_root=repo_root, expected_commit=p2_commit, label="P2"
        )
    except BaseException as exc:
        rollback_error = _rollback_closure_phase3_recovery_u2_staging(
            u2_before=u2_before,
            p2_before=p2_before,
            u1_before=u1_before,
            log_before=log_before,
            guard_before=guard_before,
            h2_commit=h2_commit,
            p2_commit=p2_commit,
            dvc_bin=dvc_bin,
            dvc_status_before=dvc_status_before,
            artifacts=artifacts,
            unmanaged_before=unmanaged_before,
            repo_root=repo_root,
        )
        if rollback_error is None:
            print(
                "Closure Phase 3 recovery U2 failed after staging: "
                f"{exc}; directed rollback restored exact1 unstaged.",
                file=sys.stderr,
            )
        else:
            print(
                "Closure Phase 3 recovery U2 failed after staging: "
                f"{exc}; ROLLBACK FAILED CLOSED: {rollback_error}",
                file=sys.stderr,
            )
        return 2

    print()
    print(f"Report written: {report_path}")
    print(
        "Exact Closure Phase 3 recovery U2 exact1A is staged; no DVC add or "
        "push ran. Publish U2 before requesting a new recovery execution."
    )
    return 0


def _closure_phase3_recovery_2_snapshot_candidate(
    *,
    stage: str,
    repo_root: Path,
    h3_commit: str | None,
    p3_commit: str | None,
) -> Any:
    if stage == "H3":
        return _snapshot_closure_phase3_recovery_2_h3_files(
            repo_root=repo_root
        )
    if stage == "P3":
        return _snapshot_closure_phase3_recovery_2_p3_files(
            repo_root=repo_root
        )
    if stage == "U3" and h3_commit is not None and p3_commit is not None:
        return _snapshot_closure_phase3_recovery_2_u3_file(
            repo_root=repo_root,
            h3_commit=h3_commit,
            p3_commit=p3_commit,
        )
    raise ClosurePhase3HPrecommitAdapterError(
        f"Closure Phase 3 recovery-2 candidate stage is malformed: {stage}"
    )


def _closure_phase3_recovery_2_require_future_boundary(
    *, stage: str, repo_root: Path
) -> None:
    _require_closure_phase3_recovery_2_future_paths_absent(
        repo_root=repo_root,
        allow_p3=stage in {"P3", "U3"},
        allow_u3=stage == "U3",
    )


def _rollback_closure_phase3_recovery_2_staging(
    *,
    stage: str,
    candidate_before: Any,
    log_before: RegistrationFileIdentity,
    u2_before: RegistrationFileIdentity,
    guards_before: tuple[
        tuple[int, int, int, int, int], tuple[int, int, int, int, int]
    ],
    head_commit: str,
    h3_commit: str | None,
    p3_commit: str | None,
    dvc_bin: str,
    dvc_status_before: Any,
    artifacts: list[DvcArtifact],
    unmanaged_before: list[Path],
    repo_root: Path,
) -> str | None:
    """Restore only H3/P3/U3 index paths and recapture every boundary."""

    config = {
        "H3": (
            CLOSURE_PHASE3_H_RECOVERY_2_STAGED_SCOPE,
            closure_phase3_recovery_2_h3_pre_stage_scope,
        ),
        "P3": (
            CLOSURE_PHASE3_P_RECOVERY_2_STAGED_SCOPE,
            closure_phase3_recovery_2_p3_pre_stage_scope,
        ),
        "U3": (
            CLOSURE_PHASE3_U_RECOVERY_2_STAGED_SCOPE,
            closure_phase3_recovery_2_u3_pre_stage_scope,
        ),
    }
    if stage not in config:
        return f"unknown recovery-2 rollback stage: {stage}"
    scope, selector = config[stage]
    errors: list[str] = []
    try:
        result = run_command(
            ["git", "restore", "--staged", "--", *sorted(scope)],
            check=False,
        )
        if result.returncode != 0:
            errors.append(
                f"directed {stage} git restore --staged failed: "
                f"exit={result.returncode}; stderr={result.stderr.strip()}"
            )
    except BaseException as exc:
        errors.append(f"directed {stage} git restore --staged raised: {exc}")
    try:
        status = _git_output(
            repo_root, "status", "--short", "--untracked-files=all"
        )
        staged = _git_output(
            repo_root, "diff", "--cached", "--name-status", "--no-renames"
        )
        if staged.strip() or not selector(status, staged, repo_root=repo_root):
            errors.append(
                f"{stage} rollback did not restore its exact fully-unstaged scope"
            )
    except BaseException as exc:
        errors.append(f"post-rollback {stage} scope validation failed: {exc}")
    recaptures: tuple[tuple[str, Callable[[], Any], Any], ...] = (
        (
            f"{stage} candidate",
            lambda: _closure_phase3_recovery_2_snapshot_candidate(
                stage=stage,
                repo_root=repo_root,
                h3_commit=h3_commit,
                p3_commit=p3_commit,
            ),
            candidate_before,
        ),
        (
            "two-record log",
            lambda: (
                _closure_phase3_recovery_2_log_identity(repo_root=repo_root)
                if stage == "H3"
                else _closure_phase3_recovery_2_log_head_identity(
                    repo_root=repo_root
                )
            ),
            log_before,
        ),
        (
            "consumed U2",
            lambda: _snapshot_closure_phase3_recovery_2_u2(
                repo_root=repo_root
            ),
            u2_before,
        ),
        (
            "attempt guards",
            lambda: _require_closure_phase3_recovery_2_guards(
                repo_root=repo_root
            ),
            guards_before,
        ),
    )
    for label, recapture, expected in recaptures:
        try:
            if recapture() != expected:
                errors.append(f"post-rollback {label} identity drifted")
        except BaseException as exc:
            errors.append(f"post-rollback {label} validation failed: {exc}")
    try:
        _require_closure_phase3_recovery_refs_at(
            repo_root=repo_root,
            expected_commit=head_commit,
            label={"H3": "U2", "P3": "H3", "U3": "P3"}[stage],
        )
        _require_closure_phase3_recovery_live_remote_at(
            repo_root=repo_root,
            expected_commit=head_commit,
            label={"H3": "U2", "P3": "H3", "U3": "P3"}[stage],
        )
        _closure_phase3_recovery_2_require_future_boundary(
            stage=stage,
            repo_root=repo_root,
        )
        if stage in {"P3", "U3"}:
            if h3_commit is None:
                raise ClosurePhase3HPrecommitAdapterError(
                    "Recovery-2 H3 commit disappeared during rollback"
                )
            _validate_closure_phase3_recovery_2_p3_bundle(
                repo_root=repo_root,
                h3_commit=h3_commit,
                require_git_publication=stage == "U3",
                allowed_dirty_paths=(
                    (CLOSURE_E0_U_RECOVERY_2_ACTIVATION_PATH.as_posix(),)
                    if stage == "U3"
                    else ()
                ),
            )
    except BaseException as exc:
        errors.append(f"post-rollback {stage} boundary failed: {exc}")
    try:
        if dvc_status_json(dvc_bin) != dvc_status_before:
            errors.append(f"post-rollback {stage} DVC status drifted")
    except BaseException as exc:
        errors.append(f"post-rollback {stage} DVC validation failed: {exc}")
    try:
        if unmanaged_ignored_heavy_paths(artifacts) != unmanaged_before:
            errors.append(
                f"post-rollback {stage} ignored-heavy inventory drifted"
            )
    except BaseException as exc:
        errors.append(
            f"post-rollback {stage} ignored-heavy validation failed: {exc}"
        )
    return "; ".join(errors) or None


def _run_closure_phase3_recovery_2_precommit(
    args: Any,
    *,
    stage: str,
    initial_status: str,
    repo_root: Path = Path("."),
) -> int:
    """Stage one exact H3/P3/U3 transition; never perform DVC add or push."""

    selectors = {
        "H3": closure_phase3_recovery_2_h3_pre_stage_scope,
        "P3": closure_phase3_recovery_2_p3_pre_stage_scope,
        "U3": closure_phase3_recovery_2_u3_pre_stage_scope,
    }
    scopes = {
        "H3": CLOSURE_PHASE3_H_RECOVERY_2_STAGED_SCOPE,
        "P3": CLOSURE_PHASE3_P_RECOVERY_2_STAGED_SCOPE,
        "U3": CLOSURE_PHASE3_U_RECOVERY_2_STAGED_SCOPE,
    }
    validators = {
        "H3": validate_closure_phase3_recovery_2_h3_staged_transaction,
        "P3": validate_closure_phase3_recovery_2_p3_staged_transaction,
        "U3": validate_closure_phase3_recovery_2_u3_staged_transaction,
    }
    if stage not in selectors:
        print(f"Unknown recovery-2 precommit stage: {stage}", file=sys.stderr)
        return 2
    selector = selectors[stage]
    scope = scopes[stage]
    validator = validators[stage]
    try:
        validate_closure_phase3_h_invocation(args)
        initial_staged = _git_output(
            repo_root, "diff", "--cached", "--name-status", "--no-renames"
        )
        if not selector(initial_status, initial_staged, repo_root=repo_root):
            raise ClosurePhase3HPrecommitAdapterError(
                f"Closure Phase 3 recovery-2 {stage} scope disappeared"
            )
        head_commit = _git_output(
            repo_root, "rev-parse", "HEAD^{commit}"
        ).strip()
        h3_commit: str | None = head_commit if stage == "P3" else None
        p3_commit: str | None = head_commit if stage == "U3" else None
        if stage == "U3":
            h3_commit = _require_closure_phase3_recovery_2_p3_history(
                repo_root=repo_root,
                p3_commit=head_commit,
            )
        candidate_before = _closure_phase3_recovery_2_snapshot_candidate(
            stage=stage,
            repo_root=repo_root,
            h3_commit=h3_commit,
            p3_commit=p3_commit,
        )
        log_before = (
            _closure_phase3_recovery_2_log_identity(repo_root=repo_root)
            if stage == "H3"
            else _closure_phase3_recovery_2_log_head_identity(
                repo_root=repo_root
            )
        )
        u2_before = _snapshot_closure_phase3_recovery_2_u2(
            repo_root=repo_root
        )
        guards_before = _require_closure_phase3_recovery_2_guards(
            repo_root=repo_root
        )
        _closure_phase3_recovery_2_require_future_boundary(
            stage=stage,
            repo_root=repo_root,
        )
        _require_closure_phase3_recovery_live_remote_at(
            repo_root=repo_root,
            expected_commit=head_commit,
            label={"H3": "U2", "P3": "H3", "U3": "P3"}[stage],
        )
        artifacts = load_configured_dvc_artifacts(args.manifest)
        unmanaged_before = unmanaged_ignored_heavy_paths(artifacts)
        dvc_bin, dvc_status_before = _initialize_precommit_dvc_observation(
            args.dvc_bin,
            formal_model_lock_active=False,
            require_locked_input_binary=False,
        )
        if dvc_bin != DEFAULT_DVC_BIN.as_posix() or dvc_status_before:
            raise ClosurePhase3HPrecommitAdapterError(
                f"Closure Phase 3 recovery-2 {stage} requires exact empty DVC status"
            )
    except (
        ClosurePhase3HPrecommitAdapterError,
        ClosureLockedEvaluationInputBundleAdapterError,
    ) as exc:
        print(str(exc), file=sys.stderr)
        return 2

    report_path = default_report_path()
    try:
        publication_result = _run_closure_phase3_recovery_2_publication_check(
            repo_root=repo_root,
            h3_commit=h3_commit if stage == "U3" else None,
            p3_commit=p3_commit if stage == "U3" else None,
        )
    except ClosurePhase3HPrecommitAdapterError as exc:
        print(str(exc), file=sys.stderr)
        return 2
    publication_report = CommandResult(
        publication_result.command,
        0,
        "OK: exact U1/U2"
        + ("/U3" if stage == "U3" else "")
        + " sealed-runtime path findings compensated; no other findings.\n",
        "",
    )

    try:
        status_before_add = _git_output(
            repo_root, "status", "--short", "--untracked-files=all"
        )
        index_before_add = _git_output(
            repo_root, "diff", "--cached", "--name-status", "--no-renames"
        )
        if not selector(status_before_add, index_before_add, repo_root=repo_root):
            raise ClosurePhase3HPrecommitAdapterError(
                f"Closure Phase 3 recovery-2 {stage} changed before staging"
            )
        if (
            _closure_phase3_recovery_2_snapshot_candidate(
                stage=stage,
                repo_root=repo_root,
                h3_commit=h3_commit,
                p3_commit=p3_commit,
            )
            != candidate_before
            or (
                _closure_phase3_recovery_2_log_identity(repo_root=repo_root)
                if stage == "H3"
                else _closure_phase3_recovery_2_log_head_identity(
                    repo_root=repo_root
                )
            )
            != log_before
            or _snapshot_closure_phase3_recovery_2_u2(repo_root=repo_root)
            != u2_before
            or _require_closure_phase3_recovery_2_guards(repo_root=repo_root)
            != guards_before
        ):
            raise ClosurePhase3HPrecommitAdapterError(
                f"Closure Phase 3 recovery-2 {stage} inputs changed before staging"
            )
        _closure_phase3_recovery_2_require_future_boundary(
            stage=stage,
            repo_root=repo_root,
        )
        _require_closure_phase3_recovery_live_remote_at(
            repo_root=repo_root,
            expected_commit=head_commit,
            label={"H3": "U2", "P3": "H3", "U3": "P3"}[stage],
        )
        if unmanaged_ignored_heavy_paths(artifacts) != unmanaged_before:
            raise ClosurePhase3HPrecommitAdapterError(
                f"Closure Phase 3 recovery-2 {stage} ignored-heavy inventory changed"
            )
    except ClosurePhase3HPrecommitAdapterError as exc:
        print(str(exc), file=sys.stderr)
        return 2

    try:
        git_add_result = run_command(
            ["git", "add", "-A", "--", *sorted(scope)],
            check=False,
        )
        if git_add_result.returncode != 0:
            raise ClosurePhase3HPrecommitAdapterError(
                f"Closure Phase 3 recovery-2 {stage} directed git add failed"
            )
        if validator(repo_root=repo_root) != candidate_before:
            raise ClosurePhase3HPrecommitAdapterError(
                f"Closure Phase 3 recovery-2 {stage} candidate changed across staging"
            )
        if (
            _snapshot_closure_phase3_recovery_2_u2(repo_root=repo_root)
            != u2_before
            or _require_closure_phase3_recovery_2_guards(repo_root=repo_root)
            != guards_before
            or (
                _closure_phase3_recovery_2_log_identity(repo_root=repo_root)
                if stage == "H3"
                else _closure_phase3_recovery_2_log_head_identity(
                    repo_root=repo_root
                )
            )
            != log_before
        ):
            raise ClosurePhase3HPrecommitAdapterError(
                f"Closure Phase 3 recovery-2 {stage} durable inputs changed across staging"
            )
        dvc_status_after = dvc_status_json(dvc_bin)
        if dvc_status_after != dvc_status_before:
            raise ClosurePhase3HPrecommitAdapterError(
                f"Closure Phase 3 recovery-2 {stage} DVC status changed"
            )
        staged_status = _git_output(
            repo_root, "diff", "--cached", "--name-status", "--no-renames"
        )
        findings = reproducibility_checks(
            staged_status=staged_status,
            selected_dvc_paths=[],
            artifacts=artifacts,
            max_manifest_hash_bytes=args.max_manifest_hash_bytes,
            verify_manifest_inputs=args.verify_manifest_inputs,
        )
        if stage == "H3":
            findings = _compensate_closure_phase3_recovery_2_manifest_findings(
                findings
            )
        non_ok = [finding for finding in findings if finding.level != "ok"]
        if non_ok:
            raise ClosurePhase3HPrecommitAdapterError(
                f"Closure Phase 3 recovery-2 {stage} reproducibility warning/failure: "
                + "; ".join(finding.message for finding in non_ok)
            )
        findings.extend(
            [
                ReproducibilityFinding(
                    "ok",
                    "phase3_recovery_2_scope",
                    "-",
                    {
                        "H3": "Exact H3 11M+4A staged on consumed U2.",
                        "P3": "Exact P3 7A staged on published H3.",
                        "U3": "Exact U3 1A staged on published P3.",
                    }[stage],
                ),
                ReproducibilityFinding(
                    "ok",
                    "phase3_recovery_2_durable_evidence",
                    CLOSURE_E0_U_OUTCOME_ACCESS_LOG_PATH.as_posix(),
                    "The exact 738-byte two-record log and both historical "
                    "guard identities remained unchanged.",
                ),
                ReproducibilityFinding(
                    "ok",
                    "phase3_recovery_2_future",
                    CLOSURE_PHASE3_RECOVERY_2_NEW_GUARD_PATH.as_posix(),
                    "Exact52 outputs, four future pointers, and guard3 remain absent.",
                ),
                ReproducibilityFinding(
                    "ok",
                    "phase3_recovery_2_dvc",
                    "-",
                    "DVC stayed empty; no DVC add or push was run.",
                ),
            ]
        )
        write_report(
            report_path,
            dry_run=False,
            selected_dvc_paths=[],
            deferred_dvc_paths=[],
            deferred_snapshot_before=None,
            deferred_snapshot_after=None,
            rejected_unmanaged_paths=unmanaged_before,
            git_status_before=initial_status,
            dvc_status_before=dvc_status_before,
            dvc_status_after=dvc_status_after,
            cloud_status_before=None,
            dvc_add_results=[],
            dvc_push_result=None,
            git_add_result=git_add_result,
            publication_check_result=publication_report,
            reproducibility_findings=findings,
            staged_status=staged_status,
            exclusive=True,
        )
        if (
            validator(repo_root=repo_root) != candidate_before
            or dvc_status_json(dvc_bin) != dvc_status_before
            or unmanaged_ignored_heavy_paths(artifacts) != unmanaged_before
        ):
            raise ClosurePhase3HPrecommitAdapterError(
                f"Closure Phase 3 recovery-2 {stage} changed while writing report"
            )
        _require_closure_phase3_recovery_live_remote_at(
            repo_root=repo_root,
            expected_commit=head_commit,
            label={"H3": "U2", "P3": "H3", "U3": "P3"}[stage],
        )
        _closure_phase3_recovery_2_require_future_boundary(
            stage=stage,
            repo_root=repo_root,
        )
    except BaseException as exc:
        rollback_error = _rollback_closure_phase3_recovery_2_staging(
            stage=stage,
            candidate_before=candidate_before,
            log_before=log_before,
            u2_before=u2_before,
            guards_before=guards_before,
            head_commit=head_commit,
            h3_commit=h3_commit,
            p3_commit=p3_commit,
            dvc_bin=dvc_bin,
            dvc_status_before=dvc_status_before,
            artifacts=artifacts,
            unmanaged_before=unmanaged_before,
            repo_root=repo_root,
        )
        if rollback_error is None:
            print(
                f"Closure Phase 3 recovery-2 {stage} failed after staging: "
                f"{exc}; directed rollback restored the exact candidate unstaged.",
                file=sys.stderr,
            )
        else:
            print(
                f"Closure Phase 3 recovery-2 {stage} failed after staging: "
                f"{exc}; ROLLBACK FAILED CLOSED: {rollback_error}",
                file=sys.stderr,
            )
        return 2

    print()
    print(f"Report written: {report_path}")
    print(
        f"Exact Closure Phase 3 recovery-2 {stage} is staged; no DVC add or "
        "push ran. Publish it linearly before the next recovery-2 gate."
    )
    return 0


def _run_closure_phase3_recovery_2_h3_precommit(
    args: Any,
    *,
    initial_status: str,
    repo_root: Path = Path("."),
) -> int:
    return _run_closure_phase3_recovery_2_precommit(
        args,
        stage="H3",
        initial_status=initial_status,
        repo_root=repo_root,
    )


def _run_closure_phase3_recovery_2_p3_precommit(
    args: Any,
    *,
    initial_status: str,
    repo_root: Path = Path("."),
) -> int:
    return _run_closure_phase3_recovery_2_precommit(
        args,
        stage="P3",
        initial_status=initial_status,
        repo_root=repo_root,
    )


def _run_closure_phase3_recovery_2_u3_precommit(
    args: Any,
    *,
    initial_status: str,
    repo_root: Path = Path("."),
) -> int:
    return _run_closure_phase3_recovery_2_precommit(
        args,
        stage="U3",
        initial_status=initial_status,
        repo_root=repo_root,
    )


def _run_closure_phase3_h4_precommit(
    args: Any,
    *,
    initial_status: str,
    repo_root: Path = Path("."),
) -> int:
    """Stage exact2M H4; keep log3/exact52 raw and run no DVC add/push."""

    staging_attempted = False
    candidate: dict[str, RegistrationFileIdentity] | None = None
    boundary: tuple[
        RegistrationFileIdentity,
        dict[str, tuple[int, str]],
        tuple[tuple[int, int, int, int, int], tuple[int, int, int, int, int]],
    ] | None = None
    dvc_bin = ""
    dvc_status_before: Any = None
    try:
        validate_closure_phase3_h_invocation(args)
        initial_index = _git_output(
            repo_root, "diff", "--cached", "--name-status", "--no-renames"
        )
        if not closure_phase3_h4_pre_stage_scope(
            initial_status, initial_index, repo_root=repo_root
        ):
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 H4 exact workspace disappeared"
            )
        _require_closure_phase3_recovery_live_remote_at(
            repo_root=repo_root,
            expected_commit=CLOSURE_PHASE3_H4_PARENT_U3_COMMIT,
            label="U3",
        )
        candidate = _snapshot_closure_phase3_h4_files(repo_root=repo_root)
        boundary = _require_closure_phase3_final_boundary(
            repo_root=repo_root, require_h4=False
        )
        artifacts = load_configured_dvc_artifacts(args.manifest)
        dvc_bin, dvc_status_before = _initialize_precommit_dvc_observation(
            args.dvc_bin,
            formal_model_lock_active=False,
            require_locked_input_binary=False,
        )
        if dvc_bin != DEFAULT_DVC_BIN.as_posix() or dvc_status_before:
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 H4 requires default DVC and empty status"
            )
        publication = _run_closure_phase3_recovery_2_publication_check(
            repo_root=repo_root,
            published_u3=True,
        )
        if (
            _snapshot_closure_phase3_h4_files(repo_root=repo_root) != candidate
            or _require_closure_phase3_final_boundary(
                repo_root=repo_root, require_h4=False
            )
            != boundary
        ):
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 H4 candidate/final bundle changed before staging"
            )
        staging_attempted = True
        add_result = run_command(
            ["git", "add", "-A", "--", *sorted(CLOSURE_PHASE3_H4_STAGED_SCOPE)],
            check=False,
        )
        if add_result.returncode != 0:
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 H4 directed git add failed"
            )
        if validate_closure_phase3_h4_staged_transaction(
            repo_root=repo_root
        ) != (candidate, boundary):
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 H4 state changed across staging"
            )
        dvc_status_after = dvc_status_json(dvc_bin)
        if dvc_status_after != dvc_status_before:
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 H4 DVC status changed across staging"
            )
        staged_status = _git_output(
            repo_root, "diff", "--cached", "--name-status", "--no-renames"
        )
        findings = reproducibility_checks(
            staged_status=staged_status,
            selected_dvc_paths=[],
            artifacts=artifacts,
            max_manifest_hash_bytes=args.max_manifest_hash_bytes,
            verify_manifest_inputs=args.verify_manifest_inputs,
        )
        if any(finding.level != "ok" for finding in findings):
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 H4 reproducibility checks did not pass"
            )
        findings.append(
            ReproducibilityFinding(
                "ok",
                "phase3_h4",
                "-",
                "Exact2M staged; log3, exact52, raw heavy outputs and guards preserved.",
            )
        )
        report_path = default_report_path()
        write_report(
            report_path,
            dry_run=False,
            selected_dvc_paths=[],
            deferred_dvc_paths=[],
            deferred_snapshot_before=None,
            deferred_snapshot_after=None,
            rejected_unmanaged_paths=[],
            git_status_before=initial_status,
            dvc_status_before=dvc_status_before,
            dvc_status_after=dvc_status_after,
            cloud_status_before=None,
            dvc_add_results=[],
            dvc_push_result=None,
            git_add_result=add_result,
            publication_check_result=CommandResult(
                publication.command,
                0,
                "OK: exact U1/U2/U3 publication findings compensated.\n",
                "",
            ),
            reproducibility_findings=findings,
            staged_status=staged_status,
            exclusive=True,
        )
        if (
            validate_closure_phase3_h4_staged_transaction(repo_root=repo_root)
            != (candidate, boundary)
            or dvc_status_json(dvc_bin) != dvc_status_before
        ):
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 H4 changed while writing its report"
            )
    except BaseException as exc:
        rollback = ""
        if staging_attempted:
            if candidate is None or boundary is None or not dvc_bin:
                rollback = "; ROLLBACK AUDIT FAILED: pre-state unavailable"
            else:
                rollback_error = _rollback_closure_phase3_h4_staging(
                    candidate=candidate,
                    boundary=boundary,
                    dvc_bin=dvc_bin,
                    dvc_status_before=dvc_status_before,
                    repo_root=repo_root,
                )
                rollback = (
                    "; directed rollback recaptured exact index/status/boundary/DVC"
                    if rollback_error is None
                    else f"; ROLLBACK AUDIT FAILED: {rollback_error}"
                )
        print(f"Closure Phase 3 H4 precommit failed: {exc}{rollback}", file=sys.stderr)
        return 2
    print(
        "Exact Closure Phase 3 H4 2M staged; no DVC add/push ran. "
        f"Report: {report_path}"
    )
    return 0


def _run_closure_phase3_final_precommit(
    args: Any,
    *,
    initial_status: str,
    initial_state: str,
    repo_root: Path = Path("."),
) -> int:
    """Register four heavy outputs and stage exact53 without a DVC push."""

    staging_attempted = False
    dvc_attempted_count = 0
    dvc_add_results: list[CommandResult] = []
    boundary: tuple[
        RegistrationFileIdentity,
        dict[str, tuple[int, str]],
        tuple[tuple[int, int, int, int, int], tuple[int, int, int, int, int]],
    ] | None = None
    dvc_bin = ""
    dvc_status_before: Any = None
    final_scope: set[str] = set()
    try:
        validate_closure_phase3_h_invocation(args)
        initial_index = _git_output(
            repo_root, "diff", "--cached", "--name-status", "--no-renames"
        )
        state = closure_phase3_final_pre_stage_scope(
            initial_status, initial_index, repo_root=repo_root
        )
        if state != initial_state or state not in {"raw", "registered"}:
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 final raw/registered state disappeared"
            )
        head = _git_output(repo_root, "rev-parse", "HEAD^{commit}").strip()
        _require_closure_phase3_recovery_live_remote_at(
            repo_root=repo_root,
            expected_commit=head,
            label="H4",
        )
        boundary = _require_closure_phase3_final_boundary(
            repo_root=repo_root, require_h4=True
        )
        artifacts = load_configured_dvc_artifacts(args.manifest)
        dvc_bin, dvc_status_before = _initialize_precommit_dvc_observation(
            args.dvc_bin,
            formal_model_lock_active=False,
            require_locked_input_binary=False,
        )
        if dvc_bin != DEFAULT_DVC_BIN.as_posix() or dvc_status_before:
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 final requires default DVC and empty status"
            )
        _expected, _formats, direct, heavy, pointers = _closure_e0_u_final_layout()
        final_scope = {
            *[path.as_posix() for path in direct],
            *[path.as_posix() for path in pointers],
            CLOSURE_E0_U_OUTCOME_ACCESS_LOG_PATH.as_posix(),
        }
        if state == "raw":
            from src.experiments import lock_closure_e0_u_activation as activation

            for index, (output_path, pointer_path) in enumerate(
                zip(heavy, pointers, strict=True), start=1
            ):
                dvc_attempted_count = index
                result = run_command(
                    [dvc_bin, "add", output_path.as_posix()],
                    check=False,
                    env=dvc_environment(),
                )
                dvc_add_results.append(result)
                if result.returncode != 0:
                    raise ClosurePhase3HPrecommitAdapterError(
                        f"DVC add {index}/4 returned {result.returncode}"
                    )
                if [os.path.lexists(repo_root / path) for path in pointers] != [
                    position < index for position in range(4)
                ]:
                    raise ClosurePhase3HPrecommitAdapterError(
                        f"DVC add {index}/4 pointer topology drifted"
                    )
                try:
                    _validate_closure_e0_u_final_dvc_pointer(
                        activation._regular_bytes(pointer_path, repo_root=repo_root),
                        pointer_path=pointer_path,
                        output_path=output_path,
                        output_payload=_read_closure_e0_u_final_dvc_output(
                            output_path, repo_root=repo_root
                        ),
                    )
                except ClosureE0UFinalBatchManifestAdapterError as exc:
                    raise ClosurePhase3HPrecommitAdapterError(str(exc)) from exc
                if _snapshot_closure_phase3_final_outputs(
                    repo_root=repo_root
                ) != boundary[1]:
                    raise ClosurePhase3HPrecommitAdapterError(
                        f"DVC add {index}/4 changed final output bytes"
                    )
        if _closure_phase3_final_pointer_state(repo_root=repo_root) != "registered":
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 final registration is not exact4"
            )
        recaptured_status = _git_output(
            repo_root, "status", "--short", "--untracked-files=all"
        )
        if closure_phase3_final_pre_stage_scope(
            recaptured_status,
            _git_output(
                repo_root, "diff", "--cached", "--name-status", "--no-renames"
            ),
            repo_root=repo_root,
        ) != "registered":
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 final registered state failed recapture"
            )
        dvc_status_after = dvc_status_json(dvc_bin)
        if dvc_status_after != dvc_status_before:
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 final DVC status drifted"
            )
        publication = _run_closure_phase3_recovery_2_publication_check(
            repo_root=repo_root,
            published_u3=True,
        )
        staging_attempted = True
        add_result = run_command(
            ["git", "add", "-A", "--", *sorted(final_scope)],
            check=False,
        )
        if add_result.returncode != 0:
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 final directed exact53 git add failed"
            )
        if validate_closure_phase3_final_staged_transaction(
            repo_root=repo_root
        ) != boundary:
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 final state changed across exact53 staging"
            )
        staged_status = _git_output(
            repo_root, "diff", "--cached", "--name-status", "--no-renames"
        )
        findings = reproducibility_checks(
            staged_status=staged_status,
            selected_dvc_paths=list(heavy),
            artifacts=artifacts,
            max_manifest_hash_bytes=args.max_manifest_hash_bytes,
            verify_manifest_inputs=args.verify_manifest_inputs,
        )
        if any(finding.level != "ok" for finding in findings):
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 final reproducibility checks did not pass"
            )
        findings.append(
            ReproducibilityFinding(
                "ok",
                "phase3_final",
                "-",
                "Exact53 staged under U3/H4; four heavy outputs registered locally.",
            )
        )
        report_path = default_report_path()
        write_report(
            report_path,
            dry_run=False,
            selected_dvc_paths=list(heavy),
            deferred_dvc_paths=[],
            deferred_snapshot_before=None,
            deferred_snapshot_after=None,
            rejected_unmanaged_paths=[],
            git_status_before=initial_status,
            dvc_status_before=dvc_status_before,
            dvc_status_after=dvc_status_after,
            cloud_status_before=None,
            dvc_add_results=dvc_add_results,
            dvc_push_result=None,
            git_add_result=add_result,
            publication_check_result=CommandResult(
                publication.command,
                0,
                "OK: exact U1/U2/U3 publication findings compensated.\n",
                "",
            ),
            reproducibility_findings=findings,
            staged_status=staged_status,
            exclusive=True,
        )
        if (
            validate_closure_phase3_final_staged_transaction(repo_root=repo_root)
            != boundary
            or dvc_status_json(dvc_bin) != dvc_status_before
        ):
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 final changed while writing its report"
            )
    except BaseException as exc:
        rollback = ""
        if staging_attempted:
            if boundary is None or not dvc_bin or not final_scope:
                rollback = "; ROLLBACK AUDIT FAILED: pre-state unavailable"
            else:
                rollback_error = _rollback_closure_phase3_final_staging(
                    final_scope=final_scope,
                    boundary=boundary,
                    dvc_bin=dvc_bin,
                    dvc_status_before=dvc_status_before,
                    repo_root=repo_root,
                )
                rollback = (
                    "; directed rollback recaptured exact index/status/boundary/DVC"
                    if rollback_error is None
                    else f"; ROLLBACK AUDIT FAILED: {rollback_error}"
                )
        elif dvc_attempted_count:
            if boundary is None or not dvc_bin:
                rollback = "; DVC FAILURE STATE AUDIT FAILED: pre-state unavailable"
            else:
                try:
                    prefix = _audit_closure_phase3_final_partial_dvc_state(
                        repo_root=repo_root,
                        boundary=boundary,
                        dvc_bin=dvc_bin,
                        dvc_status_before=dvc_status_before,
                        max_pointer_count=dvc_attempted_count,
                    )
                except BaseException as audit_exc:
                    rollback = f"; DVC FAILURE STATE AUDIT FAILED: {audit_exc}"
                else:
                    rollback = (
                        "; audited fail-closed ordered DVC prefix "
                        f"{prefix}/{dvc_attempted_count}; index/boundary/DVC exact"
                    )
        print(
            f"Closure Phase 3 final precommit failed: {exc}{rollback}; "
            "no DVC push ran.",
            file=sys.stderr,
        )
        return 2
    print(
        "Closure Phase 3 final exact53 staged; four heavy outputs are registered "
        f"locally and no DVC push ran. Report: {report_path}"
    )
    return 0


def _run_closure_phase3_h_runner_rewrite_precommit(
    args: Any,
    *,
    initial_status: str,
    repo_root: Path = Path("."),
) -> int:
    """Stage exact4M while published U anchors the future H rewrite."""

    try:
        validate_closure_phase3_h_invocation(args)
        initial_staged = _git_output(
            repo_root,
            "diff",
            "--cached",
            "--name-status",
            "--no-renames",
        )
        if not closure_phase3_h_runner_rewrite_pre_stage_scope(
            initial_status,
            initial_staged,
            repo_root=repo_root,
        ):
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 H runner rewrite exact4 scope disappeared"
            )
        physical_before = _snapshot_closure_phase3_h_files(repo_root=repo_root)
        rewrite_before = _snapshot_closure_phase3_h_runner_rewrite_files(
            repo_root=repo_root
        )
        p_before = _snapshot_closure_phase3_p_runner_rewrite_files(
            repo_root=repo_root
        )
        u_before = _snapshot_closure_phase3_u_runner_rewrite_file(
            repo_root=repo_root
        )
        outcome_log_before = _closure_phase3_h_outcome_log_identity(
            repo_root=repo_root
        )
        _require_closure_phase3_h_runner_rewrite_future_paths_absent(
            repo_root=repo_root
        )
        _require_closure_phase3_h_runner_rewrite_live_remote(
            repo_root=repo_root
        )
        artifacts = load_configured_dvc_artifacts(args.manifest)
        unmanaged_before = unmanaged_ignored_heavy_paths(artifacts)
        dvc_bin, dvc_status_before = _initialize_precommit_dvc_observation(
            args.dvc_bin,
            formal_model_lock_active=False,
            require_locked_input_binary=False,
        )
        if dvc_bin != DEFAULT_DVC_BIN.as_posix() or dvc_status_before:
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 H runner rewrite requires exact empty "
                "repository DVC status"
            )
    except (
        ClosurePhase3HPrecommitAdapterError,
        ClosureLockedEvaluationInputBundleAdapterError,
    ) as exc:
        print(str(exc), file=sys.stderr)
        return 2

    report_path = default_report_path()
    try:
        (
            publication_check_result,
            publication_compensated,
        ) = _run_closure_phase3_h_runner_rewrite_publication_check(
            repo_root=repo_root
        )
    except ClosurePhase3HPrecommitAdapterError as exc:
        print(str(exc), file=sys.stderr)
        return 2
    publication_report_result = publication_check_result
    if publication_compensated:
        publication_report_result = CommandResult(
            publication_check_result.command,
            0,
            "OK: exact current-U two-path publication exception compensated; "
            "no other findings.\n",
            "",
        )

    try:
        status_before_add = _git_output(
            repo_root, "status", "--short", "--untracked-files=all"
        )
        index_before_add = _git_output(
            repo_root,
            "diff",
            "--cached",
            "--name-status",
            "--no-renames",
        )
        if not closure_phase3_h_runner_rewrite_pre_stage_scope(
            status_before_add,
            index_before_add,
            repo_root=repo_root,
        ):
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 H runner rewrite changed during publication checks"
            )
        if (
            physical_before
            != _snapshot_closure_phase3_h_files(repo_root=repo_root)
            or rewrite_before
            != _snapshot_closure_phase3_h_runner_rewrite_files(
                repo_root=repo_root
            )
            or p_before
            != _snapshot_closure_phase3_p_runner_rewrite_files(
                repo_root=repo_root
            )
            or u_before
            != _snapshot_closure_phase3_u_runner_rewrite_file(
                repo_root=repo_root
            )
        ):
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 H/P/U runner-rewrite files changed before staging"
            )
        if outcome_log_before != _closure_phase3_h_outcome_log_identity(
            repo_root=repo_root
        ):
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 outcome access log changed before runner rewrite staging"
            )
        _require_closure_phase3_h_runner_rewrite_future_paths_absent(
            repo_root=repo_root
        )
        _require_closure_phase3_h_runner_rewrite_live_remote(
            repo_root=repo_root
        )
        if unmanaged_ignored_heavy_paths(artifacts) != unmanaged_before:
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 ignored-heavy inventory changed before "
                "runner rewrite staging"
            )
    except ClosurePhase3HPrecommitAdapterError as exc:
        print(str(exc), file=sys.stderr)
        return 2

    git_add_command = [
        "git",
        "add",
        "-A",
        "--",
        *sorted(CLOSURE_PHASE3_H_RUNNER_REWRITE_STAGED_SCOPE),
    ]
    try:
        git_add_result = run_command(git_add_command, check=False)
        if git_add_result.returncode != 0:
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 H runner rewrite directed git add failed: "
                f"exit={git_add_result.returncode}; "
                f"stderr={git_add_result.stderr.strip()}"
            )
        staged_physical = (
            validate_closure_phase3_h_runner_rewrite_staged_transaction(
                repo_root=repo_root
            )
        )
        if (
            staged_physical != physical_before
            or _snapshot_closure_phase3_h_runner_rewrite_files(
                repo_root=repo_root
            )
            != rewrite_before
            or _snapshot_closure_phase3_p_runner_rewrite_files(
                repo_root=repo_root
            )
            != p_before
            or _snapshot_closure_phase3_u_runner_rewrite_file(
                repo_root=repo_root
            )
            != u_before
        ):
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 H/P/U runner-rewrite files changed across staging"
            )
        if outcome_log_before != _closure_phase3_h_outcome_log_identity(
            repo_root=repo_root
        ):
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 outcome access log changed during runner rewrite staging"
            )
        _require_closure_phase3_h_runner_rewrite_future_paths_absent(
            repo_root=repo_root
        )
        _require_closure_phase3_h_runner_rewrite_live_remote(
            repo_root=repo_root
        )
        dvc_status_after = dvc_status_json(dvc_bin)
        if dvc_status_after != dvc_status_before:
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 DVC status changed during runner rewrite staging"
            )
        staged_status = _git_output(
            repo_root,
            "diff",
            "--cached",
            "--name-status",
            "--no-renames",
        )
        prospective_status = _git_output(
            repo_root,
            "diff",
            "--cached",
            "--name-status",
            "--no-renames",
            CLOSURE_PHASE3_H_BASE_COMMIT,
            "--",
            *sorted(CLOSURE_PHASE3_H_STAGED_SCOPE),
        )
        findings = reproducibility_checks(
            staged_status=prospective_status,
            selected_dvc_paths=[],
            artifacts=artifacts,
            max_manifest_hash_bytes=args.max_manifest_hash_bytes,
            verify_manifest_inputs=args.verify_manifest_inputs,
        )
        non_ok_findings = [
            finding for finding in findings if finding.level != "ok"
        ]
        if non_ok_findings:
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 H runner rewrite generic reproducibility "
                "checks contain warnings or failures: "
                + "; ".join(finding.message for finding in non_ok_findings)
            )
        findings.extend(
            [
                ReproducibilityFinding(
                    "ok",
                    "phase3_h_runner_rewrite_scope",
                    "-",
                    "Exact4M staged on current U; prospective R -> H stays "
                    "exact40 (24M+16A).",
                ),
                ReproducibilityFinding(
                    "ok",
                    "phase3_h_runner_rewrite_topology",
                    "-",
                    "User-only fixup/autosquash must fold exact4 into H, "
                    "drop stale P exact10 and U exact1, publish rewritten H, "
                    "then regenerate and republish P followed by U.",
                ),
                ReproducibilityFinding(
                    "ok",
                    "phase3_h_runner_rewrite_dvc",
                    "-",
                    "DVC stayed empty; no DVC add or push was run.",
                ),
                ReproducibilityFinding(
                    "ok",
                    "phase3_h_runner_rewrite_outcomes",
                    CLOSURE_E0_U_OUTCOME_ACCESS_LOG_PATH.as_posix(),
                    "Current P exact10 and U exact1 stayed byte-bound, "
                    "exact52/pointers/guards stayed absent, and the tracked "
                    "outcome log stayed empty.",
                ),
                ReproducibilityFinding(
                    "ok",
                    "phase3_h_runner_rewrite_publication_guard",
                    CLOSURE_E0_U_ACTIVATION_PATH.as_posix(),
                    (
                        "Generic publication guard passed without compensation."
                        if not publication_compensated
                        else "Generic publication guard real rc=1 was "
                        "compensated only for the exact byte-bound current U "
                        "line containing its two sealed .venv runtime paths; "
                        "every other section remained absent."
                    ),
                ),
            ]
        )
        write_report(
            report_path,
            dry_run=False,
            selected_dvc_paths=[],
            deferred_dvc_paths=[],
            deferred_snapshot_before=None,
            deferred_snapshot_after=None,
            rejected_unmanaged_paths=unmanaged_before,
            git_status_before=initial_status,
            dvc_status_before=dvc_status_before,
            dvc_status_after=dvc_status_after,
            cloud_status_before=None,
            dvc_add_results=[],
            dvc_push_result=None,
            git_add_result=git_add_result,
            publication_check_result=publication_report_result,
            reproducibility_findings=findings,
            staged_status=staged_status,
            exclusive=True,
        )
        if (
            validate_closure_phase3_h_runner_rewrite_staged_transaction(
                repo_root=repo_root
            )
            != physical_before
            or _snapshot_closure_phase3_h_runner_rewrite_files(
                repo_root=repo_root
            )
            != rewrite_before
            or _snapshot_closure_phase3_p_runner_rewrite_files(
                repo_root=repo_root
            )
            != p_before
            or _snapshot_closure_phase3_u_runner_rewrite_file(
                repo_root=repo_root
            )
            != u_before
            or _closure_phase3_h_outcome_log_identity(repo_root=repo_root)
            != outcome_log_before
            or dvc_status_json(dvc_bin) != dvc_status_before
            or unmanaged_ignored_heavy_paths(artifacts) != unmanaged_before
        ):
            raise ClosurePhase3HPrecommitAdapterError(
                "Closure Phase 3 H runner rewrite changed while writing its report"
            )
        _require_closure_phase3_h_runner_rewrite_future_paths_absent(
            repo_root=repo_root
        )
        _require_closure_phase3_h_runner_rewrite_live_remote(
            repo_root=repo_root
        )
    except BaseException as exc:
        return _abort_closure_phase3_h_post_add(
            exc,
            mode="runner_rewrite",
            physical_before=physical_before,
            amend_before=rewrite_before,
            outcome_log_before=outcome_log_before,
            dvc_bin=dvc_bin,
            dvc_status_before=dvc_status_before,
            artifacts=artifacts,
            unmanaged_before=unmanaged_before,
            repo_root=repo_root,
            p_before=p_before,
            u_before=u_before,
        )

    print()
    print(f"Report written: {report_path}")
    print(
        "Exact Closure Phase 3 H runner rewrite patch is staged; no DVC "
        "add or push ran. Drop stale P and U, then regenerate both."
    )
    return 0


